import * as D from '../packages/domain/src/index.ts';
import { updateWorld, freezeWorld } from '../packages/domain/src/draft.ts';
import { exactNavigation, groundActionAttempts } from '../apps/server/src/action-grounding.ts';
import { upgradeWorldState } from '../apps/server/src/upgrade-world.ts';
const checks=[];
const ensure=(value,message)=>{if(!value)throw Error(message);};
let w=freezeWorld(D.advanceWorld(freezeWorld(D.createWorld(73)),1).world);
const player=D.PLAYER_ID,npc=D.NPC_ID;
let hidden=updateWorld(w,d=>{d.entities[npc].name='NeverDisclosedName';if(d.observerIdentities?.[player])delete d.observerIdentities[player][npc];});
ensure(!exactNavigation('follow NeverDisclosedName',hidden,player),'Global name leaked into exact grounding');
let captured='';
await groundActionAttempts(hidden,player,{operations:[{localId:'private-target',act:{kind:'proposal',description:'Follow that person cautiously',targetEntityId:npc,mode:'enqueue'}}]},[],{judge:async request=>{captured+=JSON.stringify(request);return {answers:{route:{choice:'unresolved',probabilities:{unresolved:1}}}};},generate:async()=>{throw Error('Unexpected generation');},record:async()=>{}});
ensure(!captured.includes('NeverDisclosedName'),'Global name leaked into semantic grounding');
checks.push({name:'observer-scoped-action-names',passed:true});
const sleeping=w.statusEffectPolicy.definitions.find(d=>d.whileActive.some(op=>op.restrictCapabilities?.capabilities.includes('perception')));
ensure(sleeping,'Missing perception-restricting native status');
let asleep=D.executeCommand(w,{id:'review-sleep',actorId:player,type:'status-effect',targetId:player,definitionId:sleeping.id,operation:'activate'});
ensure(asleep.outcome.ok,'Sleep activation failed '+asleep.outcome.message);
asleep=D.advanceWorld(freezeWorld(asleep.world),1);
ensure(Object.keys(asleep.world.perceptionEpisodes?.[player]??{}).length===0,'Perception loss retained identity episode');
ensure(!(asleep.world.visiblePeople?.[player]?.length),'Perception loss retained live sight');
checks.push({name:'status-loss-clears-exposure-and-recognition',passed:true});
let following=D.executeCommand(w,{id:'review-follow',actorId:player,type:'follow',targetId:npc});ensure(following.outcome.ok,'Native following failed');
const block=structuredClone(sleeping);block.id='review-mobility-block';block.label='Review mobility block';block.occupiesAction=false;block.requires={field:{target:'$subject',name:'alive',operator:'equal',value:true}};delete block.activationCondition;delete block.automaticActivation;delete block.automaticDeactivation;block.whileActive=[{restrictCapabilities:{target:'$subject',capabilities:['locomotion']}}];delete block.onActivate;delete block.onDeactivate;
const admitted=D.admitStatusEffectPolicy(following.world,{...following.world.statusEffectPolicy,revision:following.world.statusEffectPolicy.revision+1,definitions:[...following.world.statusEffectPolicy.definitions,block]},following.world.statusEffectPolicy.revision);ensure(admitted.outcome.ok,'Review status policy rejected '+admitted.outcome.message);
const blocked=updateWorld(admitted.world,d=>{ensure(D.activateStatusEffect(d,block,{subject:d.entities[player],source:d.entities[player],actionTarget:d.entities[player]},[],'review'),'Could not activate block');});
const ended=D.advanceWorld(freezeWorld(blocked),1);ensure(!ended.world.entities[player].actor.action,'Capability loss stranded follow activity');
checks.push({name:'follow-reconciles-locomotion-loss',passed:true});
const old=structuredClone(w);const rows=old.memories[player];rows.push({id:'late-old',actorId:player,kind:'episode',source:'internal',summary:'An old fact',at:10,entityIds:[],importance:1,sequence:20},{id:'earlier-old',actorId:player,kind:'episode',source:'internal',summary:'An earlier fact',at:9,entityIds:[],importance:1,sequence:19});const identities=rows.map(r=>r.id).sort();const nextId=old.nextId;upgradeWorldState(old);D.validateWorldModules(old);ensure(JSON.stringify(old.memories[player].map(r=>r.id).sort())===JSON.stringify(identities)&&nextId===old.nextId,'Upgrade changed evidence identity');
checks.push({name:'lossless-existing-source-order-upgrade',passed:true});
// New native evidence can be edited through its owner without changing earlier snapshots.
const awareness=w.experience.awareness[player][0];ensure(awareness,'Missing native evidence');
const edited=updateWorld(w,d=>{const replacement={...awareness,text:'Reviewed observation',content:'Reviewed observation'};ensure(D.mutateExperience(d,player,{operation:'update',entryId:'awareness:'+awareness.eventId,entry:{source:'awareness',value:replacement}})!==null,'Owned evidence edit failed');});
ensure(w.experience.awareness[player][0].text!==edited.experience.awareness[player][0].text,'Evidence alias mutation');
checks.push({name:'frozen-owned-evidence-edit-isolation',passed:true});
console.log(JSON.stringify({scope:'Ad hoc native execution and injected no-provider grounding; no automated suites or live model-quality claim.',paidModelCalls:0,checks},null,2));
